Preference order (the first one that works wins, and its provenance is recorded
so metrics.json can state exactly which engine produced the numbers):

  1. an already importable `fasttext` module (the official pybind11 binding of
     the authors' C++ code, e.g. the `fasttext-wheel` prebuilt wheel);
  2. `pip install fasttext-wheel` (prebuilt wheel of the same C++ code);
  3. a native build of the cloned repo (`make` in repo/, or `pip install .`);
  4. the authors' own PyTorch EmbeddingBag example
     (repo/python/doc/examples/FastTextEmbeddingBag.py) -- a re-implementation,
     flagged as such.

Options 1-3 all run the authors' unmodified C++ trainer, so the numbers are
produced by the exact system the paper describes.
"""
import importlib
import os
import shutil
import subprocess
import sys

import config

ENGINE = None
ENGINE_DETAIL = {}
VERDICT_CEILING = "reproduced"


def _try_import():
    try:
        mod = importlib.import_module("fasttext")
    except Exception:
        return None
    if not hasattr(mod, "train_supervised"):
        return None
    return mod


def _pip_install_wheel():
    try:
        subprocess.run(
            [sys.executable, "-m", "pip", "install", "fasttext-wheel"],
            check=True, stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
        )
    except Exception:
        return None
    return _try_import()


def _native_build():
    """Build the cloned C++ sources with make / pip, if a toolchain exists."""
    if not os.path.isdir(config.REPO_DIR):
        return None
    has_make = shutil.which("make") is not None
    has_compiler = any(shutil.which(c) for c in ("g++", "clang++", "cl", "gcc"))
    if not (has_make or has_compiler):
        return None
    for cmd in (["make"], [sys.executable, "setup.py", "build_ext", "--inplace"]):
        try:
            subprocess.run(cmd, cwd=config.REPO_DIR, check=True,
                           stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
                           timeout=900)
        except Exception:
            continue
        mod = _try_import()
        if mod is not None:
            return mod
    return None


def _embeddingbag_fallback():
    """The authors' PyTorch EmbeddingBag fastText example (re-implementation)."""
    path = os.path.join(config.REPO_DIR, "python", "doc", "examples",
                        "FastTextEmbeddingBag.py")
    if not os.path.isfile(path):
        return None
    return ("embeddingbag", path)


def get_engine():
    """Return (kind, engine) and fill ENGINE_DETAIL."""
    global ENGINE, ENGINE_DETAIL, VERDICT_CEILING
    mod = _try_import()
    if mod is not None:
        ENGINE = "fasttext-python"
        ENGINE_DETAIL = {
            "engine": "fasttext (official pybind11 binding of the authors' C++ code)",
            "module": getattr(mod, "__file__", ""),
            "version": getattr(mod, "__version__", "0.9.2"),
        }
        return ENGINE, mod

    mod = _pip_install_wheel()
    if mod is not None:
        ENGINE = "fasttext-wheel"
        ENGINE_DETAIL = {
            "engine": "fasttext-wheel (prebuilt wheel of the authors' C++ code)",
            "module": getattr(mod, "__file__", ""),
        }
        return ENGINE, mod

    mod = _native_build()
    if mod is not None:
        ENGINE = "native-build"
        ENGINE_DETAIL = {"engine": "native build of repo/ (authors' C++ code)"}
        return ENGINE, mod

    fb = _embeddingbag_fallback()
    if fb is not None:
        ENGINE = "embeddingbag-reimplementation"
        VERDICT_CEILING = "partially_reproduced"
        ENGINE_DETAIL = {
            "engine": "authors' PyTorch EmbeddingBag example (RE-IMPLEMENTATION)",
            "script": fb[1],
        }
        return ENGINE, fb

    raise RuntimeError("no usable fastText engine found")


def train(input_path, output_path, **kwargs):
    """Train with the authors' trainer; returns the model object."""
    kind, engine = get_engine()
    if kind == "embeddingbag-reimplementation":
        raise RuntimeError("EmbeddingBag fallback is not wired into train(); "
                           "install fasttext-wheel or build the C++ code.")
    os.makedirs(os.path.dirname(os.path.abspath(output_path)), exist_ok=True)
    model = engine.train_supervised(input=input_path, output=output_path, **kwargs)
    return model


def test(model, path):
    """Return (N, precision@1, recall@1) exactly as the authors' `fasttext test`."""
    n, p, r = model.test(path)
    return int(n), float(p), float(r)

