def _text_key(line):
    """Article-text key of a normalized fastText line (label token dropped)."""
    parts = line.split(" ", 1)
    text = parts[1] if len(parts) > 1 else ""
    return " ".join(text.split())


def _split_train_valid(rows, n_valid, rng):
    """Split `rows` into (search, valid) so no article text appears on both sides.

    AG News contains duplicate articles; a plain random row split would put the
    same text in the training part and in the validation holdout, leaking the
    answer.  Duplicates are therefore grouped into buckets, the bucket ids are
    shuffled with the fixed seed, and whole buckets are assigned to one side.
    """
    buckets = {}
    for row in rows:
        buckets.setdefault(_text_key(row), []).append(row)
    bucket_ids = list(buckets.keys())
    rng.shuffle(bucket_ids)
    valid_rows, search_rows = [], []
    for bid in bucket_ids:
        bucket = buckets[bid]
        if len(valid_rows) + len(bucket) <= n_valid:
            valid_rows.extend(bucket)
        else:
            search_rows.extend(bucket)
    return search_rows, valid_rows, len(buckets)


