# ---------------------------------------------------------------- target
# The comparison targets are read from the claim contract (state/claim_contract.json)
# so that no paper result number is typed into this code.  They are used ONLY for
# the pass/fail tolerance check reported in metrics.json -- never as an input to
# training, which is driven exclusively by the protocol hyperparameters above.
CONTRACT_PATH = os.path.join(WORKSPACE, "state", "claim_contract.json")


def load_contract():
    """Return the claim contract dict, or None if it is not available."""
    try:
        import json
        with open(CONTRACT_PATH, "r", encoding="utf-8") as fh:
            return json.load(fh)
    except Exception:
        return None


def claim_target(claim_id, default=None):
    """Reported value of a claim from the contract (for the tolerance check only)."""
    contract = load_contract()
    if contract:
        for claim in contract.get("claims", []):
            if claim.get("id") == claim_id:
                return claim.get("value", default)
    return default


def contract_tolerance(default=1.0):
    contract = load_contract()
    if contract:
        tol = contract.get("tolerance", {})
        if isinstance(tol, dict) and tol.get("value") is not None:
            return float(tol["value"])
    return default


TARGET_ACCURACY = claim_target("C1")          # Table 1, AG, fastText h=10, bigram
TARGET_NO_BIGRAM = claim_target("C2")         # Table 1, AG, fastText h=10 (no bigram)
TOLERANCE = contract_tolerance()              # absolute percentage points

